contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // Try to call withdraw and Command; if this contract is not Owner initially, both must revert and not change Owner or balance.
    function run(uint sendAmount, address target, bytes calldata data) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (0) + (sendAmount)); require(sendAmount <= 1000000000000000000000000000000);
        require(address(this).balance >= sendAmount, "insufficient test balance");

        // observe before state
        address ownerBefore = c.Owner(); if (__ESBMC_reverted()) return;
        uint balBefore = address(c).balance;

        // attempt withdraw
        bool withdrawReverted;
        c.withdraw{value: 0}(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            withdrawReverted = true;
        } else {
            withdrawReverted = false;
        }

        // observe after withdraw
        address ownerAfterWithdraw = c.Owner(); if (__ESBMC_reverted()) return;
        uint balAfterWithdraw = address(c).balance;

        // attempt Command
        bool commandReverted;
        c.Command{value: sendAmount}(target, data); bool __rev1 = __ESBMC_reverted(); if (__rev1) {
            commandReverted = true;
        } else {
            commandReverted = false;
        }

        // observe after Command
        address ownerAfterCommand = c.Owner(); if (__ESBMC_reverted()) return;
        uint balAfterCommand = address(c).balance;

        // Single assert: if this contract was not Owner initially, then both calls reverted and Owner and balance remained unchanged throughout.
        assert((address(this) == ownerBefore) || (withdrawReverted && commandReverted && ownerAfterWithdraw == ownerBefore && ownerAfterCommand == ownerBefore && balBefore == balAfterWithdraw && balAfterWithdraw == balAfterCommand));
    }

    receive() external payable {}
}

